select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, lag(amount, 2) over (partition by account_id order by txn_time, id) as prev_amount, sum(amount) over (order by txn_time, id rows between unbounded preceding and current row) as cumulative_amount, last_value(amount) ignore nulls over (order by amount, id rows between unbounded preceding and current row) as last_known_amount from transactions
